import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.Dsf4_p3t.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":1787565302000}'),i={name:"guide/architecture.md"};function r(o,e,p,d,l,c){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>NeoFlux uses a two-layer architecture that cleanly separates business logic from rendering.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Application Layer (main thread)                     │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌──────────┐  ┌──────────┐  ┌──────────────────┐   │</span></span>
<span class="line"><span>│  │ Widget   │  │ Taitank  │  │ EventLoop +      │   │</span></span>
<span class="line"><span>│  │ Tree     │→ │ Layout   │  │ Coroutines       │   │</span></span>
<span class="line"><span>│  └──────────┘  └──────────┘  └────────┬─────────┘   │</span></span>
<span class="line"><span>│                                       │              │</span></span>
<span class="line"><span>│                              RenderCommand           │</span></span>
<span class="line"><span>│                                       ▼              │</span></span>
<span class="line"><span>│  ┌──────────────────────────────────────────────┐   │</span></span>
<span class="line"><span>│  │  SPSC RingQueue (lock-free, FIFO)            │   │</span></span>
<span class="line"><span>│  └───────────────────────┬──────────────────────┘   │</span></span>
<span class="line"><span>└──────────────────────────┼──────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>┌──────────────────────────▼──────────────────────────┐</span></span>
<span class="line"><span>│  Render Layer (render thread)                       │</span></span>
<span class="line"><span>│                                                      │</span></span>
<span class="line"><span>│  ┌─────────────────┐    ┌──────────────────────┐    │</span></span>
<span class="line"><span>│  │ RenderCommand   │    │ tgfx (mobile)        │    │</span></span>
<span class="line"><span>│  │ Consumer        │───▶│ GLFW + OpenGL (desk) │    │</span></span>
<span class="line"><span>│  └─────────────────┘    └──────────────────────┘    │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="application-layer" tabindex="-1">Application Layer <a class="header-anchor" href="#application-layer" aria-label="Permalink to &quot;Application Layer&quot;">​</a></h2><p>The application layer runs on the main thread and is responsible for:</p><ul><li><strong>Widget tree management</strong>: Building, updating, and tearing down widget trees.</li><li><strong>Taitank layout</strong>: Running flexbox layout on the widget tree each frame.</li><li><strong>Input dispatch</strong>: Hit-testing and routing pointer/scroll events.</li><li><strong>Event loop</strong>: Processing events, driving coroutines, and triggering frames.</li><li><strong>Render command generation</strong>: Converting laid-out widgets into <code>RenderCommand</code> objects.</li></ul><h3 id="frame-pipeline" tabindex="-1">Frame Pipeline <a class="header-anchor" href="#frame-pipeline" aria-label="Permalink to &quot;Frame Pipeline&quot;">​</a></h3><p>Each frame in the application layer follows this sequence:</p><ol><li><strong>Poll events</strong> — GLFW input events are dispatched to the widget tree.</li><li><strong>Build dirty widgets</strong> — Widgets marked with <code>MarkNeedsBuild()</code> are rebuilt.</li><li><strong>Layout</strong> — <code>Taitank::DoLayout</code> computes widget positions and sizes.</li><li><strong>Paint</strong> — Each widget&#39;s <code>Paint()</code> method generates <code>RenderCommand</code>s.</li><li><strong>Submit</strong> — Commands are pushed to the SPSC ring queue.</li></ol><p>A frame is only processed when the <code>frame_dirty_</code> flag is set (by input events, route changes, or <code>MarkFrameDirty()</code>), reducing idle CPU usage.</p><h2 id="render-layer" tabindex="-1">Render Layer <a class="header-anchor" href="#render-layer" aria-label="Permalink to &quot;Render Layer&quot;">​</a></h2><p>The render layer runs on a dedicated thread and is responsible for:</p><ul><li><strong>Consuming commands</strong> — Pulling <code>RenderCommand</code>s from the ring queue.</li><li><strong>Drawing</strong> — Executing draw calls via tgfx (mobile) or OpenGL (desktop).</li><li><strong>Buffer swapping</strong> — Presenting the rendered frame to the screen.</li></ul><h3 id="desktop-rendering-glfw-bridge" tabindex="-1">Desktop Rendering (GLFW Bridge) <a class="header-anchor" href="#desktop-rendering-glfw-bridge" aria-label="Permalink to &quot;Desktop Rendering (GLFW Bridge)&quot;">​</a></h3><p>On desktop platforms, NeoFlux uses GLFW for window management and OpenGL 3.3 for rendering. The <code>GlfwBridge</code> class wraps GLFW calls and provides:</p><ul><li>Window creation and resizing</li><li>Mouse/keyboard input callbacks</li><li>OpenGL context management</li><li>Framebuffer size queries</li></ul><h3 id="mobile-rendering-tgfx" tabindex="-1">Mobile Rendering (tgfx) <a class="header-anchor" href="#mobile-rendering-tgfx" aria-label="Permalink to &quot;Mobile Rendering (tgfx)&quot;">​</a></h3><p>On mobile platforms, NeoFlux uses <a href="https://github.com/Tencent/tgfx" target="_blank" rel="noreferrer">tgfx</a> for rendering. tgfx provides a unified 2D graphics API that backs onto the platform&#39;s native graphics API (Vulkan/Metal/GLES).</p><h2 id="spsc-ring-queue" tabindex="-1">SPSC Ring Queue <a class="header-anchor" href="#spsc-ring-queue" aria-label="Permalink to &quot;SPSC Ring Queue&quot;">​</a></h2><p>Communication between layers uses a <strong>single-producer, single-consumer</strong> lock-free ring queue:</p><ul><li><strong>Producer</strong>: Application layer (main thread)</li><li><strong>Consumer</strong>: Render layer (render thread)</li><li><strong>Capacity</strong>: Configurable via <code>--render_queue_capacity</code> (default 2048)</li><li><strong>Elements</strong>: <code>RenderCommand</code> flat struct (draw rect, draw rounded rect, draw text, clip, translate, save/restore, begin/end frame)</li></ul><p>The queue uses cache-line-aligned head/tail counters and <code>std::construct_at</code> / <code>std::destroy_at</code> for safe element construction, supporting non-trivially copyable types like <code>std::string</code>.</p><h3 id="bitwise-index-wrapping" tabindex="-1">Bitwise Index Wrapping <a class="header-anchor" href="#bitwise-index-wrapping" aria-label="Permalink to &quot;Bitwise Index Wrapping&quot;">​</a></h3><p>Capacity is rounded up to the next power of two (<code>std::bit_ceil</code>) so that index wrapping uses a single bitwise AND instead of integer modulo:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// In SpscRingQueue:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mask_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> capacity_ </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           // e.g. capacity=2048 -&gt; mask=2047 (0x7FF)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">next_head </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (head </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mask_;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // 1 cycle AND vs ~20-40 cycles for %</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This is why <code>--render_queue_capacity</code> is rounded up: any value becomes a power of two, enabling the <code>&amp; mask_</code> optimization. A capacity of 2048 stores 2047 elements (one slot is reserved for full/empty distinction).</p></div><p>The same pattern applies elsewhere:</p><ul><li>Frame logging: <code>(frames_rendered &amp; 63U) == 0U</code> instead of <code>% 60</code></li><li>Even/odd tests: <code>(x &amp; 1U) == 0U</code> instead of <code>x % 2 == 0</code></li><li>Integer halving: <code>x &gt;&gt; 1</code> instead of <code>x / 2</code> (integers only)</li></ul><h2 id="thread-safety" tabindex="-1">Thread Safety <a class="header-anchor" href="#thread-safety" aria-label="Permalink to &quot;Thread Safety&quot;">​</a></h2><ul><li>The widget tree is only accessed from the main thread.</li><li>The render queue is the only shared data structure.</li><li>The render thread only reads <code>RenderCommand</code> values from the queue; it never touches the widget tree.</li><li>Coroutines are scheduled and resumed exclusively on the main thread by the <code>EventLoop</code>.</li></ul><h2 id="data-flow-deep-dive" tabindex="-1">Data Flow Deep Dive <a class="header-anchor" href="#data-flow-deep-dive" aria-label="Permalink to &quot;Data Flow Deep Dive&quot;">​</a></h2><p>This section traces a complete frame from user input to pixels on screen.</p><h3 id="_1-input-reception-platform-bridge" tabindex="-1">1. Input Reception (Platform Bridge) <a class="header-anchor" href="#_1-input-reception-platform-bridge" aria-label="Permalink to &quot;1. Input Reception (Platform Bridge)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GLFW mouse callback / Android touch event</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>PlatformBridge::input_callback_ (set by Application)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Application::DispatchPointerEvent(pos, action, button)</span></span></code></pre></div><p>The platform bridge receives raw input events and forwards them to the Application via a registered callback. On desktop, <code>GlfwBridge</code> converts GLFW enum values to <code>PlatformBridge::InputAction</code> values (note: GLFW_RELEASE=0 but <code>kRelease=1</code>, so a conversion function is required).</p><h3 id="_2-hit-testing-event-dispatch-application-layer" tabindex="-1">2. Hit Testing &amp; Event Dispatch (Application Layer) <a class="header-anchor" href="#_2-hit-testing-event-dispatch-application-layer" aria-label="Permalink to &quot;2. Hit Testing &amp; Event Dispatch (Application Layer)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DispatchPointerEvent</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► HitTest(pos) ── recursive tree traversal ──► deepest widget</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► OnPointerDown/Up/Move/Enter/Exit(local_pos)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        └─► MarkFrameDirty()  ◄── sets frame_dirty_ = true</span></span></code></pre></div><p><code>HitTest</code> walks the widget tree in reverse child order (top-most first), checking each widget&#39;s <code>bounds_</code>. A hit-test cache avoids re-traversal when the pointer moves but the layout hasn&#39;t changed. During an active drag, move events bypass hit testing and go directly to the pressed widget.</p><h3 id="_3-widget-state-change-dirty-marking" tabindex="-1">3. Widget State Change &amp; Dirty Marking <a class="header-anchor" href="#_3-widget-state-change-dirty-marking" aria-label="Permalink to &quot;3. Widget State Change &amp; Dirty Marking&quot;">​</a></h3><p>When a widget handles an event (e.g. <code>Button</code> changes press state, <code>Draggable</code> updates offset), it calls <code>MarkNeedsBuild()</code> to schedule a rebuild. This sets a dirty flag on the widget and propagates up to mark the frame dirty.</p><h3 id="_4-frame-build-eventloop" tabindex="-1">4. Frame Build (EventLoop) <a class="header-anchor" href="#_4-frame-build-eventloop" aria-label="Permalink to &quot;4. Frame Build (EventLoop)&quot;">​</a></h3><p>When <code>frame_dirty_</code> is true, the next <code>EventLoop::Tick()</code> executes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tick()</span></span>
<span class="line"><span>  ├─► PollEvents()          ── platform bridge polls input</span></span>
<span class="line"><span>  ├─► RunReadyCoroutines()  ── 4-phase coroutine scheduler</span></span>
<span class="line"><span>  │     ├─ Promote yields (yield_handles_ → pending)</span></span>
<span class="line"><span>  │     ├─ Resume pending coroutines</span></span>
<span class="line"><span>  │     ├─ Collect completed (erase from active_tasks_)</span></span>
<span class="line"><span>  │     └─ Fire expired timers (lookup Task in active_tasks_ before resume)</span></span>
<span class="line"><span>  │</span></span>
<span class="line"><span>  ├─► Build dirty widgets   ── Build() for widgets with needs_build_ flag</span></span>
<span class="line"><span>  ├─► PerformLayout()       ── Taitank flexbox layout pass</span></span>
<span class="line"><span>  └─► Paint()               ── generate RenderCommands</span></span></code></pre></div><h3 id="_5-layout-taitank" tabindex="-1">5. Layout (Taitank) <a class="header-anchor" href="#_5-layout-taitank" aria-label="Permalink to &quot;5. Layout (Taitank)&quot;">​</a></h3><p><code>PerformLayout(width, height)</code> walks the widget tree:</p><ol><li>Each <code>Container</code> creates/updates a Taitank flex node with its properties (flex direction, padding, margin, justify/align).</li><li>Leaf widgets (<code>Text</code>, <code>Button</code>) report intrinsic size via <code>OnMeasure()</code>.</li><li><code>Taitank::DoLayout(root_node, width, height)</code> computes all positions/sizes.</li><li><code>ReadLayoutRecursive()</code> copies computed bounds back into each widget&#39;s <code>bounds_</code>.</li></ol><h3 id="_6-paint-command-generation" tabindex="-1">6. Paint &amp; Command Generation <a class="header-anchor" href="#_6-paint-command-generation" aria-label="Permalink to &quot;6. Paint &amp; Command Generation&quot;">​</a></h3><p>Each widget&#39;s <code>Paint(RenderContext&amp;)</code> method emits <code>RenderCommand</code>s:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Widget::Paint()</span></span>
<span class="line"><span>  ├─► MakeSave()              ── push transform/clip state</span></span>
<span class="line"><span>  ├─► MakeTranslate(x, y)     ── move to widget position</span></span>
<span class="line"><span>  ├─► MakeClipRect(bounds)    ── clip to widget bounds</span></span>
<span class="line"><span>  ├─► MakeDrawRect/RoundedRect ── background</span></span>
<span class="line"><span>  ├─► MakeDrawText(text, ...) ── text rendering</span></span>
<span class="line"><span>  ├─► children-&gt;Paint()       ── recursive</span></span>
<span class="line"><span>  └─► MakeRestore()           ── pop state</span></span></code></pre></div><p>Commands are pushed to the ring queue as they are generated. A frame is delimited by <code>MakeBeginFrame()</code> and <code>MakeEndFrame()</code> commands.</p><h3 id="_7-spsc-ring-queue-transfer" tabindex="-1">7. SPSC Ring Queue Transfer <a class="header-anchor" href="#_7-spsc-ring-queue-transfer" aria-label="Permalink to &quot;7. SPSC Ring Queue Transfer&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application (producer)             Render (consumer)</span></span>
<span class="line"><span>       │                                  │</span></span>
<span class="line"><span>       │  TryPush(RenderCommand)          │</span></span>
<span class="line"><span>       │─────────────────────────────────►│</span></span>
<span class="line"><span>       │  (atomic head/tail, no lock)     │</span></span>
<span class="line"><span>       │                                  │  TryPop()</span></span>
<span class="line"><span>       │                                  │</span></span></code></pre></div><p>The queue uses cache-line-aligned atomic head/tail counters to avoid false sharing. <code>std::construct_at</code> places the element in raw storage; <code>std::destroy_at</code> cleans up after pop. Capacity is rounded up to the next power of two for fast modulo via bitwise AND.</p><h3 id="_8-render-thread-consumption" tabindex="-1">8. Render Thread Consumption <a class="header-anchor" href="#_8-render-thread-consumption" aria-label="Permalink to &quot;8. Render Thread Consumption&quot;">​</a></h3><p>The render thread runs <code>RenderLoop()</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>RenderLoop()</span></span>
<span class="line"><span>  ├─► Wait for frame signal (semaphore, blocks when no work)</span></span>
<span class="line"><span>  ├─► MakeContextCurrent()   ── platform_bridge_-&gt;MakeContextCurrent()</span></span>
<span class="line"><span>  ├─► Consume all commands in queue:</span></span>
<span class="line"><span>  │     ├─► BeginFrame       ── clear screen</span></span>
<span class="line"><span>  │     ├─► Save/Restore     ── transform/clip stack</span></span>
<span class="line"><span>  │     ├─► DrawRect         ── filled rectangle</span></span>
<span class="line"><span>  │     ├─► DrawRoundedRect  ── rounded rectangle (shader)</span></span>
<span class="line"><span>  │     ├─► DrawText         ── glyph rendering via FontManager + tgfx</span></span>
<span class="line"><span>  │     └─► EndFrame</span></span>
<span class="line"><span>  └─► SwapBuffers()          ── platform_bridge_-&gt;SwapBuffers()</span></span></code></pre></div><p>On desktop, <code>GlfwBridge</code> provides the OpenGL context and window. On mobile, <code>MobileBridge</code> provides the platform surface (ANativeWindow/CAMetalLayer) and tgfx renders directly.</p><h3 id="_9-presentation" tabindex="-1">9. Presentation <a class="header-anchor" href="#_9-presentation" aria-label="Permalink to &quot;9. Presentation&quot;">​</a></h3><p><code>SwapBuffers()</code> presents the rendered frame to the window manager. The render thread then waits on the semaphore for the next frame, consuming zero CPU while idle.</p><h2 id="rendercommand-types" tabindex="-1">RenderCommand Types <a class="header-anchor" href="#rendercommand-types" aria-label="Permalink to &quot;RenderCommand Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><code>kNoop</code></td><td>No operation (padding)</td></tr><tr><td><code>kBeginFrame</code></td><td>Start a new frame (clear buffer)</td></tr><tr><td><code>kEndFrame</code></td><td>End frame (flush)</td></tr><tr><td><code>kDrawRect</code></td><td>Filled axis-aligned rectangle</td></tr><tr><td><code>kDrawRoundedRect</code></td><td>Filled rectangle with rounded corners</td></tr><tr><td><code>kDrawText</code></td><td>Text string at position with font/size/color</td></tr><tr><td><code>kSave</code></td><td>Push transform/clip state</td></tr><tr><td><code>kRestore</code></td><td>Pop transform/clip state</td></tr><tr><td><code>kTranslate</code></td><td>Apply translation offset</td></tr><tr><td><code>kClipRect</code></td><td>Set clipping rectangle</td></tr></tbody></table><ul><li><code>pressed_widget_</code> uses <code>std::weak_ptr</code> to avoid dangling references across frames.</li><li><code>frame_dirty_</code> is an <code>std::atomic&lt;bool&gt;</code> for lock-free dirty flag checks.</li></ul>`,63)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
